CREATE TRIGGER catalog_work_settings_delete AFTER DELETE ON settings WHEN OLD.key IN ('store_name','logo_media_id','hero_media_id','announcement_text','media_public_base_url','seo_title_template','canonical_base_url','currency','checkout_email_cap','checkout_account_cap','checkout_ip_cap','cart_max_qty','cart_max_lines','order_max_units','checkout_session_minutes','refund_retry_cap','refund_stuck_minutes') BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, target_revision, processed_revision, created_at, updated_at) VALUES ('settings:store', 'settings', 'store', 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
